def build_row(topic_number, title, hook, facts, image_url, tags, caption):
    facts_text = ". ".join(facts)
    video_prompt = (
        f"Create a 30-second vertical history short about {title}. "
        f"Hook: {hook} Cover: {facts_text}. "
        f"Tone: dramatic, fast-paced, documentary style. 9:16 vertical."
    )
    on_screen_bullets = " | ".join(facts)
    hashtags = " ".join(f"#{t}" for t in tags)
    return {
        "topic_number": topic_number,
        "title": title,
        "hook": hook,
        "video_prompt": video_prompt,
        "on_screen_bullets": on_screen_bullets,
        "image_url": image_url,
        "hashtags": hashtags,
        "caption": caption,
    }


def read_existing_rows():
    rows = []
    with INPUT_CSV.open(newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            rows.append(row)
    return rows


def main():
    existing = read_existing_rows()
    rows = list(existing)
    start = len(existing) + 1
    for i, topic in enumerate(NEW_TOPICS, start=start):
        rows.append(build_row(
            i,
            topic["title"],
            topic["hook"],
            topic["facts"],
            topic["image"],
            topic["tags"],
            topic["caption"],
        ))
    fieldnames = [
        "topic_number", "title", "hook", "video_prompt",
        "on_screen_bullets", "image_url", "hashtags", "caption",
    ]
    with OUTPUT_CSV.open("w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        for row in rows:
            writer.writerow({k: row[k] for k in fieldnames})
    print(f"Wrote {len(rows)} rows to {OUTPUT_CSV}")


if __name__ == "__main__":
    main()
